begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('71000000-0000-4000-8000-000000000001','annotations-owner@example.invalid'),('71000000-0000-4000-8000-000000000002','annotations-other@example.invalid');
delete from private.app_owner;
insert into private.app_owner(user_id,github_user_id) values('71000000-0000-4000-8000-000000000001','10001');
create temp table annotation_fixture(doc jsonb);
insert into annotation_fixture values('__DOCUMENT__'::jsonb);
grant select on annotation_fixture to authenticated;
insert into public.portfolio_media(id,owner_id,path,mime,bytes) values
 ('81000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001/portfolio/81000000-0000-4000-8000-000000000001.webp','image/webp',10),
 ('81000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000002/portfolio/81000000-0000-4000-8000-000000000002.webp','image/webp',10);
select ok(private.validate_portfolio((select doc from annotation_fixture),'71000000-0000-4000-8000-000000000001'),'old snapshots valid without annotations');
select ok(not has_function_privilege('anon','private.validate_portfolio(jsonb,uuid)','execute'),'validator remains private');
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.save_portfolio((select doc from annotation_fixture),0)$$,'old snapshot saved');
select lives_ok($$select public.publish_portfolio(1)$$,'old snapshot published');
reset role;
update annotation_fixture set doc=jsonb_set(doc,'{locales,vi,annotations}','[{"id":"note1","field":"summary","itemId":"","quote":"stale quote","occurrence":1,"title":"Context","body":"Plain text","image":"media:81000000-0000-4000-8000-000000000001","href":"https://example.com","appearance":"highlight","enabled":true}]');
select ok(private.validate_portfolio((select doc from annotation_fixture),'71000000-0000-4000-8000-000000000001'),'independent VI annotations valid with stale quote');
select ok(private.validate_portfolio(jsonb_set(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,field}','"work.description"'),'{locales,vi,annotations,0,itemId}','"deleted-work"'),'71000000-0000-4000-8000-000000000001'),'deleted item reference stays valid');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,itemId}','"wrong-root-item"'),'71000000-0000-4000-8000-000000000001'),'root field rejects nonempty item');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,field}','"projects.description"'),'71000000-0000-4000-8000-000000000001'),'entity field requires item');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,quote}','""'),'71000000-0000-4000-8000-000000000001'),'empty quote rejected');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,quote}',to_jsonb(repeat('x',501))),'71000000-0000-4000-8000-000000000001'),'quote bounds enforced');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,title}',to_jsonb(repeat('x',161))),'71000000-0000-4000-8000-000000000001'),'title bounds enforced');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,title}',to_jsonb(repeat('😀',81))),'71000000-0000-4000-8000-000000000001'),'Unicode title respects JavaScript UTF16 length bound');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,body}',to_jsonb(repeat('x',2001))),'71000000-0000-4000-8000-000000000001'),'body bounds enforced');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,occurrence}','0'),'71000000-0000-4000-8000-000000000001'),'zero occurrence rejected');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,occurrence}','1001'),'71000000-0000-4000-8000-000000000001'),'occurrence max enforced');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,occurrence}','1.5'),'71000000-0000-4000-8000-000000000001'),'fractional occurrence rejected');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,image}','"https://evil.test/remote.svg"'),'71000000-0000-4000-8000-000000000001'),'remote annotation image denied');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,href}','"javascript:alert(1)"'),'71000000-0000-4000-8000-000000000001'),'executable href denied');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,href}','"https://user:pass@evil.test"'),'71000000-0000-4000-8000-000000000001'),'URL credentials denied');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,html}','"<b>unsafe</b>"'),'71000000-0000-4000-8000-000000000001'),'unknown HTML configuration denied');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations}',jsonb_build_array((select doc#>'{locales,vi,annotations,0}' from annotation_fixture),(select doc#>'{locales,vi,annotations,0}' from annotation_fixture))),'71000000-0000-4000-8000-000000000001'),'duplicate annotation IDs rejected');
select ok(not private.validate_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations}',(select jsonb_agg(jsonb_set((select doc#>'{locales,vi,annotations,0}' from annotation_fixture),'{id}',to_jsonb('n'||n))) from generate_series(1,101)n)),'71000000-0000-4000-8000-000000000001'),'annotation count bounded');
set local role authenticated;
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from annotation_fixture),'{locales,vi,annotations,0,image}','"media:81000000-0000-4000-8000-000000000002"'),2)$$,'23514','invalid_document','direct RPC rejects another owner annotation-only media');
select lives_ok($$select public.save_portfolio((select doc from annotation_fixture),2)$$,'annotation draft saved');
set local role anon;
select is((select count(*)::int from public.read_published_portfolio_media('81000000-0000-4000-8000-000000000001')),0,'annotation-only draft media private');
select ok(not (select document->'locales'->'vi' ? 'annotations' from public.read_published_portfolio()),'public old snapshot unchanged by draft');
set local role authenticated;
select lives_ok($$select public.publish_portfolio(3)$$,'annotation publication atomic');
set local role anon;
select is((select count(*)::int from public.read_published_portfolio_media('81000000-0000-4000-8000-000000000001')),1,'current annotation-only image exposed');
select is((select document#>>'{locales,vi,annotations,0,title}' from public.read_published_portfolio()),'Context','published annotation DTO readable');
select throws_ok($$select * from public.portfolio_sites$$,'42501',null,'draft table still denied');
select throws_ok($$select * from public.portfolio_versions$$,'42501',null,'history table still denied');
set local role authenticated;
select lives_ok($$select public.save_portfolio((select doc #- '{locales,vi,annotations}' from annotation_fixture),4)$$,'remove optional annotations from draft');
select lives_ok($$select public.publish_portfolio(5)$$,'republish old compatible shape');
set local role anon;
select is((select count(*)::int from public.read_published_portfolio_media('81000000-0000-4000-8000-000000000001')),0,'historical annotation image no longer public');
reset role;
select * from finish();
rollback;
